	if got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestComposeReviewPrompt_TaskAddsFindingOutputFormat(t *testing.T) {
	t.Parallel()
	cfg := reviewtypes.RunConfig{
		Task: "Review for real defects.",
	}
