func TestComposeReviewPrompt_PositiveTimeoutAddsBudgetHint(t *testing.T) {
	t.Parallel()
	// A reviewer that knows its deadline can pace itself; one that doesn't
	// runs its full pipeline and gets killed mid-verify with all work lost.
	cfg := reviewtypes.RunConfig{
