		"Bash(git status:*)", "Bash(git blame:*)", "Bash(git rev-parse:*)",
	} {
		if !members[want] {
			t.Errorf("allowlist missing %q; got %q", want, allowed)
		}
	}
	for _, banned := range []string{"Edit", "Write", "MultiEdit", "NotebookEdit", "Bash", "Bash(git:*)"} {
